def main():
    with open(DOCS_PATH, "r") as f:
        docs = json.load(f)
    by_id = {d["id"]: d for d in docs}
    missing = [k for k in MC_SUMMARIES if k not in by_id]
    if missing:
        raise SystemExit(f"Unknown IDs: {missing}")
    changed = 0
    for doc_id, summary in MC_SUMMARIES.items():
        if by_id[doc_id].get("summary") != summary:
            by_id[doc_id]["summary"] = summary
            changed += 1
    with open(DOCS_PATH, "w") as f:
        json.dump(docs, f, indent=2)
    print(f"Updated {changed} of {len(MC_SUMMARIES)} Medi-Cal summaries.")


if __name__ == "__main__":
    main()
